@using sv_8632e104885649aca267d9374222d150.Models
@using sv_8632e104885649aca267d9374222d150.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    @if (_loading)
    {
        <p class="text-muted">Loading notification preferences…</p>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_toastMessage
                <button type="button" class="btn-close" @onclick="() => _toastMessage = null"></button>
            </div>
        }

        <h4>Notifications</h4>
        <p class="text-muted">Choose how you want to be notified</p>
        <hr />

        <div class="mb-4">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif"
                       checked="@_emailNotifications"
                       @onchange="e => _emailNotifications = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="emailNotif">
                    Email Notifications
                    <small class="d-block text-muted">Receive notifications via email</small>
                </label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif"
                       checked="@_pushNotifications"
                       @onchange="e => _pushNotifications = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="pushNotif">
                    Push Notifications
                    <small class="d-block text-muted">Receive push notifications in your browser</small>
                </label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest"
                       checked="@_weeklyDigest"
                       @onchange="e => _weeklyDigest = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="weeklyDigest">
                    Weekly Digest
                    <small class="d-block text-muted">Receive a weekly summary of activity</small>
                </label>
            </div>
        </div>

        <h5>Muted Channels</h5>
        <p class="text-muted">Uncheck channels you don't want notifications from</p>

        @if (_allChannels.Count > 0)
        {
            <div class="channel-list mb-4">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                               checked="@isMuted"
                               @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="@($"ch-{channel}")">
                            @channel @(isMuted ? "(muted)" : "")
                        </label>
                    </div>
                }
            </div>
        }
        else
        {
            <p class="text-muted fst-italic">No channels available.</p>
        }

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Preferences")
        </button>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new();

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        // Channels come from the prefs — in a real app this might be a separate call
        _allChannels = new List<string>(prefs.MutedChannels);
        if (_allChannels.Count == 0)
        {
            _allChannels = new List<string> { "General", "Engineering", "Design", "Marketing", "Support" };
        }
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _toastMessage = "Notification preferences saved!";
        _saving = false;
    }
}

