@using sv_8632e104885649aca267d9374222d150.Services
@inject ISettingsService SettingsService

<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center"
         style="cursor: pointer;" @onclick="() => _expanded = !_expanded">
        <strong>Change Password</strong>
        <span>@(_expanded ? "▲" : "▼")</span>
    </div>
    @if (_expanded)
    {
        <div class="card-body">
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible fade show">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="mb-3">
                <label class="form-label" for="currentPwd">Current Password</label>
                <input id="currentPwd" type="password" class="form-control" @bind="_currentPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="newPwd">New Password</label>
                <input id="newPwd" type="password" class="form-control" @bind="_newPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="confirmPwd">Confirm Password</label>
                <input id="confirmPwd" type="password" class="form-control" @bind="_confirmPassword" />
            </div>

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@_saving">
                @(_saving ? "Updating…" : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    private bool _expanded;
    private bool _saving;
    private string? _message;
    private bool _isError;

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    private async Task UpdatePasswordAsync()
    {
        _message = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            _message = "Please fill in all password fields.";
            _isError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _message = "New password and confirmation do not match.";
            _isError = true;
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _message = "Password updated successfully!";
            _isError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _message = $"Failed to update password: {ex.Message}";
            _isError = true;
        }
        _saving = false;
    }
}

@using sv_8632e104885649aca267d9374222d150.Models

<div class="table-responsive">
    <table class="table table-striped align-middle">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("g")</td>
                    <td>
                        @if (session.Id == CurrentSessionId)
                        {
                            <span class="badge bg-success">Current</span>
                        }
                        else if (_confirmingSessionId == session.Id)
                        {
                            <div class="d-flex gap-2 align-items-center">
                                <span class="text-danger">Revoke?</span>
                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session.Id)">
                                    Yes
                                </button>
                                <button class="btn btn-outline-secondary btn-sm" @onclick="CancelRevoke">
                                    No
                                </button>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-outline-danger btn-sm"
                                    @onclick="() => RequestRevoke(session.Id)">
                                Revoke
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        _confirmingSessionId = sessionId;
    }

    private void CancelRevoke()
    {
        _confirmingSessionId = null;
    }

    private async Task ConfirmRevoke(string sessionId)
    {
        _confirmingSessionId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}

