@using sv_8632e104885649aca267d9374222d150.Models

<div class="table-responsive">
    <table class="table table-striped align-middle">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("g")</td>
                    <td>
                        @if (session.Id == CurrentSessionId)
                        {
                            <span class="badge bg-success">Current</span>
                        }
                        else if (_confirmingSessionId == session.Id)
                        {
                            <div class="d-flex gap-2 align-items-center">
                                <span class="text-danger">Revoke?</span>
                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session.Id)">
                                    Yes
                                </button>
                                <button class="btn btn-outline-secondary btn-sm" @onclick="CancelRevoke">
                                    No
                                </button>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-outline-danger btn-sm"
                                    @onclick="() => RequestRevoke(session.Id)">
                                Revoke
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        _confirmingSessionId = sessionId;
    }

    private void CancelRevoke()
    {
        _confirmingSessionId = null;
    }

    private async Task ConfirmRevoke(string sessionId)
    {
        _confirmingSessionId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}

