@using sv_8632e104885649aca267d9374222d150.Models
@using sv_8632e104885649aca267d9374222d150.Services
@inject ISettingsService SettingsService

<div class="security-section">
    @if (_loading)
    {
        <p class="text-muted">Loading security settings…</p>
    }
    else
    {
        <h4>Security</h4>
        <p class="text-muted">Manage your account security</p>
        <hr />

        <ChangePasswordPanel />

        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <br />
                    <small class="text-muted">Add an extra layer of security to your account</small>
                </div>
                <div class="d-flex align-items-center gap-2">
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" id="twoFactor"
                               checked="@_twoFactorEnabled"
                               @onchange="e => _twoFactorEnabled = (bool)(e.Value ?? false)" />
                    </div>
                </div>
            </div>
        </div>

        @if (_lastPasswordChange.HasValue)
        {
            <p class="text-muted mb-4">
                <small>Last password change: @_lastPasswordChange.Value.ToString("f")</small>
            </p>
        }

        <h5>Active Sessions</h5>

        @if (_sessions.Count > 0)
        {
            <ActiveSessionsTable Sessions="_sessions"
                                 CurrentSessionId="@_sessions[0].Id"
                                 OnRevoke="RevokeSessionAsync" />
        }
        else
        {
            <p class="text-muted fst-italic">No active sessions.</p>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions.ToList();
        _loading = false;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions.RemoveAll(s => s.Id == sessionId);
    }
}

