@using sv_8632e104885649aca267d9374222d150.Models
@using sv_8632e104885649aca267d9374222d150.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings…</p>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_toastMessage
                <button type="button" class="btn-close" @onclick="() => _toastMessage = null"></button>
            </div>
        }

        <h4>Appearance</h4>
        <p class="text-muted">Customize how the app looks and feels</p>
        <hr />

        <div class="mb-4">
            <h6>Theme</h6>
            @foreach (var theme in _themes)
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Font Size</h6>
            @foreach (var size in _fontSizes)
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"fs-{size}")" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <label class="form-label" for="language"><h6 class="d-inline">Language</h6></label>
            <select id="language" class="form-select" style="max-width: 250px;"
                    @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode"
                       checked="@_compactMode"
                       @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="compactMode">
                    Compact Mode
                    <small class="d-block text-muted">Reduce spacing and padding throughout the app</small>
                </label>
            </div>
        </div>

        <h6>Live Preview</h6>
        <div class="preview-area @GetPreviewClasses()">
            <div class="preview-header">Sample Header</div>
            <p class="preview-text">
                This is a preview of how your content will look with the selected settings.
                The theme, font size, and compact mode changes are reflected here.
            </p>
            <button class="preview-button">Sample Button</button>
        </div>

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_theme.ToLowerInvariant() switch
        {
            "dark" => "preview-dark",
            "system" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_fontSize.ToLowerInvariant() switch
        {
            "small" => "preview-font-small",
            "large" => "preview-font-large",
            _ => "preview-font-medium"
        });
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _toastMessage = "Appearance settings saved!";
        _saving = false;
    }
}

.appearance-section {
    max-width: 600px;
}

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.3s ease;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #495057;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
