toolArgs.file_text:
.appearance-section {
    max-width: 600px;
}

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.3s ease;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #495057;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.5rem;
    line-height: 1.2;
}

.preview-header {
    font-weight: 700;
    font-size: 1.2em;
    margin-bottom: 0.5rem;
}

.preview-dark .preview-header {
    color: #cba6f7;
}

.preview-text {
    margin-bottom: 0.75rem;
}

.preview-button {
    border: none;
    padding: 0.4rem 1rem;
    border-radius: 0.25rem;
    cursor: default;
    font-size: inherit;
}

.preview-light .preview-button {
    background: #0d6efd;
    color: white;
}

.preview-dark .preview-button {
    background: #89b4fa;
    color: #1e1e2e;
}

.preview-system .preview-button {
    background: #6c757d;
    color: white;
}

